var s=`0813-kondowole`;var t=`world-0813`;var i=`MW`;var n=`eastern-africa`;var o=4;var r=31;var d={en:`Kondowole`,ua:`Кондоволе`};var l={en:`Kondowole is a Malawi dish made with cassava flour, peanut stew paste. This home-scale recipe assigns measured ingredients to the steps where they are used. Uses processed cassava flour only. Never consume inadequately processed raw cassava.`,ua:`Кондоволе, страва кухні країни Малаві. Основні складники: борошно маніоку, арахісова паста для рагу. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Використовуйте тільки оброблене маніокове борошно; не вживайте неправильно підготовлений сирий маніок.`};var u=[{en:`Use commercially detoxified cassava flour. Add it steadily to hot water and beat into a thick elastic paste, never using raw or untreated cassava.`,ua:`Використовуйте лише промислово знешкоджене маніокове борошно. Поступово додавайте його в гарячу воду й вимішуйте густу еластичну масу, не беріть сирий маніок.`,t:[`boiling`],m:20,i:[[`cassava-flour`,370,`g`],[`water`,720,`ml`],[`table-salt`,5,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 8 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 8 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:8,i:[[`water`,140,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut-stew-paste`,90,`g`]]}];var h={slug:s,id:t,country:`MW`,region:n,servings:4,minutes:31,title:d,text:l,steps:u};export{i as country,h as default,t as id,r as minutes,n as region,o as servings,s as slug,u as steps,l as text,d as title};